HDAM_DB.MAPLEMONK.EXCHANGE_RATES ) A WHERE RW = 1 ), rates_asof as ( select d.ORDER_DATE, r.EUR_INR, r.USD_INR, r.GBP_INR, r.AUD_INR, r.JPY_INR, r.SGD_INR, r.CAD_INR, r.AED_INR from (select distinct ORDER_TIMESTAMP::date as ORDER_DATE from VAHDAM_DB.MAPLEMONK.VAHDAM_DB_Amazon_Vendor_central_Sales_consolidated where ORDER_TIMESTAMP is not null) d join rates r on r.date <= d.ORDER_DATE qualify row_number() over (partition by d.ORDER_DATE order by r.date desc) = 1 ) select FI.* ,CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.LINE_ITEM_SALES * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.LINE_ITEM_SALES WHEN FI.CURRENCY = \'USD\' THEN FI.LINE_ITEM_SALES * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.LINE_ITEM_SALES * EX.GBP_INR WHEN FI.CURRENCY = \'AUD\' THEN FI.LINE_ITEM_SALES * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.LINE_ITEM_SALES * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.LINE_ITEM_SALES * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.LINE_ITEM_SALES * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.LINE_ITEM_SALES * EX.AED_INR END AS LINE_ITEM_SALES_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.TAX * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.TAX WHEN FI.CURRENCY = \'USD\' THEN FI.TAX * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.TAX * EX.GBP_INR WHEN FI.CURRENCY = \'AUD\' THEN FI.TAX * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.TAX * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.TAX * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.TAX * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.TAX * EX.AED_INR END AS TAX_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.DISCOUNT * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.DISCOUNT WHEN FI.CURRENCY = \'USD\' THEN FI.DISCOUNT * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.DISCOUNT * EX.GBP_INR WHEN FI.CURRENCY = \'AUD\' THEN FI.DISCOUNT * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.DISCOUNT * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.DISCOUNT * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.DISCOUNT * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.DISCOUNT * EX.AED_INR END AS DISCOUNT_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.TOTAL_SALES * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.TOTAL_SALES WHEN FI.CURRENCY = \'USD\' THEN FI.TOTAL_SALES * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.TOTAL_SALES * EX.GBP_INR WHEN FI.CURRENCY = \'AUD\' THEN FI.TOTAL_SALES * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.TOTAL_SALES * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.TOTAL_SALES * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.TOTAL_SALES * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.TOTAL_SALES * EX.AED_INR END AS TOTAL_SALES_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.TOTAL_SALES * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.TOTAL_SALES WHEN FI.CURRENCY = \'USD\' THEN FI.TOTAL_SALES * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.TOTAL_SALES * EX.GBP_INR WHEN FI.CURRENCY = \'AUD\' THEN FI.TOTAL_SALES * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.TOTAL_SALES * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.TOTAL_SALES * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.TOTAL_SALES * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.TOTAL_SALES * EX.AED_INR END AS SUBTOTAL_PRICE_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.SHIPPING_PRICE * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.SHIPPING_PRICE WHEN FI.CURRENCY = \'USD\' THEN FI.SHIPPING_PRICE * EX.USD_INR WHEN FI.CURRENCY = \'GBP\' THEN FI.SHIPPING_PRICE * EX.GBP_INR WHEN FI.CURRENCY = \'AUS\' THEN FI.SHIPPING_PRICE * EX.AUD_INR WHEN FI.CURRENCY = \'JPY\' THEN FI.SHIPPING_PRICE * EX.JPY_INR WHEN FI.CURRENCY = \'SGD\' THEN FI.SHIPPING_PRICE * EX.SGD_INR WHEN FI.CURRENCY = \'CAD\' THEN FI.SHIPPING_PRICE * EX.CAD_INR WHEN FI.CURRENCY = \'AED\' THEN FI.SHIPPING_PRICE * EX.AED_INR END AS SHIPPING_PRICE_INR, CASE WHEN FI.CURRENCY = \'EUR\' THEN FI.TOTAL_SECONDARY_SALES * EX.EUR_INR WHEN FI.CURRENCY = \'INR\' THEN FI.TOTAL_SECONDARY_SALES WHEN FI.CURRENCY = \'USD\' THEN FI.TOTAL_SECONDARY_SALES * EX.USD_INR WHEN FI.CURRENCY =